import{_ as t,o,c as e,a2 as s}from"./chunks/framework.Bqa2y7hU.js";const k=JSON.parse('{"title":"QQ 官方：Webhook 回调","description":"用 Webhook 回调方式接入 QQ 官方机器人，需要公网域名并把回调地址填回开放平台。","frontmatter":{"title":"QQ 官方：Webhook 回调","description":"用 Webhook 回调方式接入 QQ 官方机器人，需要公网域名并把回调地址填回开放平台。"},"headers":[],"relativePath":"platforms/qq-official-webhook.md","filePath":"platforms/qq-official-webhook.md","lastUpdated":1789790467000}'),i={name:"platforms/qq-official-webhook.md"};function l(d,a,r,h,n,c){return o(),e("div",null,[...a[0]||(a[0]=[s(`<h1 id="qq-官方-webhook-回调-📮" tabindex="-1">QQ 官方：Webhook 回调 📮 <a class="header-anchor" href="#qq-官方-webhook-回调-📮" aria-label="Permalink to &quot;QQ 官方：Webhook 回调 📮&quot;">​</a></h1><p>Webhook 模式和 WebSocket 网关模式接入的是同一类机器人，区别只在<strong>谁发起连接</strong>：网关模式是框架主动连平台，回调模式是平台主动把事件推给你。</p><p>因此这页的重点不是「怎么配机器人」，而是「回调地址怎么来、填到哪里去」。如果你没有公网域名，直接用 <a href="/RuaBot.Doc/platforms/qq-official">WebSocket 网关</a> 更省事。</p><h2 id="_1-和网关模式的差异一览" tabindex="-1">1. 和网关模式的差异一览 <a class="header-anchor" href="#_1-和网关模式的差异一览" aria-label="Permalink to &quot;1. 和网关模式的差异一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对比项</th><th>WebSocket 网关</th><th>Webhook 回调</th></tr></thead><tbody><tr><td>谁发起连接</td><td>框架连平台</td><td>平台回调你</td></tr><tr><td>公网域名</td><td>不需要</td><td><strong>必须</strong></td></tr><tr><td>控制台里的配置</td><td>只填凭据与环境</td><td>凭据、环境，外加一个回调地址要填回平台</td></tr><tr><td>机器人详情页</td><td>常规 5 个 Tab</td><td>多出一个「事件转发」Tab</td></tr><tr><td>适用场景</td><td>绝大多数情况</td><td>已有稳定公网域名、希望回调直连</td></tr></tbody></table><h2 id="_2-先配好公网域名" tabindex="-1">2. 先配好公网域名 <a class="header-anchor" href="#_2-先配好公网域名" aria-label="Permalink to &quot;2. 先配好公网域名&quot;">​</a></h2><p>回调地址里的协议与域名<strong>不是手填的</strong>，而是取自「平台设置 → 站点」里的两个配置：</p><table tabindex="0"><thead><tr><th>配置项</th><th>作用</th></tr></thead><tbody><tr><td><code>webhook_protocol</code></td><td>回调地址用什么协议，决定是 <code>http</code> 还是 <code>https</code></td></tr><tr><td><code>webhook_domain</code></td><td>回调地址用哪个域名</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">务必配公网域名</p><p>如果这两个值没配，回调地址会<strong>退化成当前浏览器访问控制台所用的 Host</strong>。那样生成出来的地址只在你本机网络里有效，QQ 开放平台根本回调不到，表现为「事件一直收不到」。</p><p>配域名、上 HTTPS、反向代理这些事，完整步骤见 <a href="/RuaBot.Doc/platforms/callback">回调地址与公网域名</a>。</p></div><h2 id="_3-在控制台添加机器人" tabindex="-1">3. 在控制台添加机器人 <a class="header-anchor" href="#_3-在控制台添加机器人" aria-label="Permalink to &quot;3. 在控制台添加机器人&quot;">​</a></h2><p>进入「我的机器人」，点「添加机器人」：</p><ul><li>第一步：平台选 <code>qq_official</code></li><li>第二步：填名称、<code>AppID</code>、<code>AppSecret</code>、环境（<code>production</code> 或 <code>sandbox</code>）</li><li>连接方式：选 <strong>Webhook 回调</strong></li></ul><p>提交后机器人立即上线，不需要重启服务。</p><h2 id="_4-把回调地址填回-qq-开放平台" tabindex="-1">4. 把回调地址填回 QQ 开放平台 <a class="header-anchor" href="#_4-把回调地址填回-qq-开放平台" aria-label="Permalink to &quot;4. 把回调地址填回 QQ 开放平台&quot;">​</a></h2><p>选完 Webhook 后，控制台会弹出一个回调地址，形如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{协议}://{域名}/api/webhooks/adapters/qq_official/{机器人UUID}</span></span></code></pre></div><p>其中 <code>{协议}</code> 与 <code>{域名}</code> 就是第 2 步里配的 <code>webhook_protocol</code> 与 <code>webhook_domain</code>，<code>{机器人UUID}</code> 是这台机器人在控制台里的唯一标识。</p><p>把这个地址<strong>原样复制</strong>，填到 QQ 开放平台的回调配置里。注意：</p><ul><li>不要漏掉末尾的机器人 UUID 那一段</li><li>改过 <code>webhook_domain</code> 之后，地址会变，需要回平台上重新填一次</li></ul><h2 id="_5-确认生效" tabindex="-1">5. 确认生效 <a class="header-anchor" href="#_5-确认生效" aria-label="Permalink to &quot;5. 确认生效&quot;">​</a></h2><p>回到机器人详情页：</p><ul><li>「设置」Tab 里的连接方式应显示为 Webhook 回调</li><li>页面上会<strong>多出一个「事件转发」Tab</strong>，这是 Webhook 模式独有的</li></ul><p>事件转发 Tab 用来查看 / 配置事件往哪里转发。如果你在「设置」里没看到它，说明当前不是 Webhook 模式。</p><details class="details custom-block"><summary>截图占位</summary><p>截两处：一是选 Webhook 后弹出回调地址的对话框（地址可打码，露出结构即可）；二是机器人详情页顶部 Tab 栏，露出「事件转发」这个多出来的 Tab。</p></details><h2 id="_6-收不到回调怎么查" tabindex="-1">6. 收不到回调怎么查 <a class="header-anchor" href="#_6-收不到回调怎么查" aria-label="Permalink to &quot;6. 收不到回调怎么查&quot;">​</a></h2><h3 id="症状-qq-开放平台提示回调地址校验失败" tabindex="-1">症状：QQ 开放平台提示回调地址校验失败 <a class="header-anchor" href="#症状-qq-开放平台提示回调地址校验失败" aria-label="Permalink to &quot;症状：QQ 开放平台提示回调地址校验失败&quot;">​</a></h3><ul><li><strong>原因</strong>：回调地址填错，或域名解析不到、证书不对。</li><li><strong>处理方式</strong>：在浏览器里直接打开那个回调地址对应的域名，确认能解析、HTTPS 证书有效；再对照控制台弹出的地址逐字符核对。</li></ul><h3 id="症状-平台上校验通过-但机器人收不到任何事件" tabindex="-1">症状：平台上校验通过，但机器人收不到任何事件 <a class="header-anchor" href="#症状-平台上校验通过-但机器人收不到任何事件" aria-label="Permalink to &quot;症状：平台上校验通过，但机器人收不到任何事件&quot;">​</a></h3><ul><li><strong>原因</strong>：回调地址退化成当前访问的 Host（<code>webhook_domain</code> 没配），或者反向代理没把 <code>Host</code> 头透传。</li><li><strong>处理方式</strong>：到「平台设置 → 站点」把 <code>webhook_domain</code> 配成真实公网域名，重新生成地址并回填平台；再按 <a href="/RuaBot.Doc/platforms/callback">回调地址与公网域名</a> 检查反向代理配置。</li></ul><h3 id="症状-换个浏览器-换台电脑登录控制台-回调地址就变了" tabindex="-1">症状：换个浏览器 / 换台电脑登录控制台，回调地址就变了 <a class="header-anchor" href="#症状-换个浏览器-换台电脑登录控制台-回调地址就变了" aria-label="Permalink to &quot;症状：换个浏览器 / 换台电脑登录控制台，回调地址就变了&quot;">​</a></h3><ul><li><strong>原因</strong>：同样是 <code>webhook_domain</code> 没配，地址跟着访问用的 Host 走。</li><li><strong>处理方式</strong>：配好 <code>webhook_domain</code> 之后地址就固定了。</li></ul><h3 id="症状-反向代理后所有回调都是-404" tabindex="-1">症状：反向代理后所有回调都是 404 <a class="header-anchor" href="#症状-反向代理后所有回调都是-404" aria-label="Permalink to &quot;症状：反向代理后所有回调都是 404&quot;">​</a></h3><ul><li><strong>原因</strong>：代理只转发了部分路径，回调路径没放行。</li><li><strong>处理方式</strong>：确认代理放行了管理面端口上的 <code>/api/webhooks/</code> 路径，端口用途区分见 <a href="/RuaBot.Doc/platforms/callback">回调地址与公网域名</a>。</li></ul><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Nginx：把回调路径转发到管理面端口（示例，按你的实际监听地址调整）</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">location</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> /api/webhooks/ </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_pass </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://&lt;你的服务器IP&gt;:8080;     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 框架与代理同机时填回环地址</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Host $host;              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 必须透传 Host</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">X-Real-IP $remote_addr;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/RuaBot.Doc/platforms/callback">回调地址与公网域名</a></li><li><a href="/RuaBot.Doc/platforms/qq-official">QQ 官方：WebSocket 网关</a></li><li><a href="/RuaBot.Doc/deploy/reverse-proxy">反向代理与 HTTPS</a></li></ul>`,36)])])}const b=t(i,[["render",l]]);export{k as __pageData,b as default};
